(function runJijiAutofill_14() {
  console.clear();
  console.log('%c🚀 JIJI AD #14: Starlink & Starlink Mini High-Speed Setu...', 'color:#10b981; font-weight:bold; font-size:16px;');

  const AD = {
    id: 14,
    title: "Starlink & Starlink Mini High-Speed Setup • Whole-House Mesh WiFi 6",
    price: 35000,
    priceStr: "₦35,000",
    imgName: "ad_14_starlink_installation.png",
    imgB64: "",
    desc: "Tired of slow GSM mobile internet and frequent subsea fiber optic cable cuts?\n\nGet professional Starlink satellite dish mounting, precision alignment, and whole-building mesh WiFi 6 coverage with ZERO dead zones across your property.\n\nWHAT WE DELIVER:\n- Starlink Standard & Starlink Mini roof / wall bracket mounting (zero obstruction)\n- Precision satellite dish azimuth alignment for maximum 150-250 Mbps speeds\n- Whole-duplex Mesh WiFi 6 extension (strong signal in all rooms & compound)\n- Bypass mode setup with Dual-WAN seamless failover routers (Starlink + 4G)\n- Inverter & surge protection integration (guards against NEPA voltage spikes)\n\nEnjoy unlimited ultra-fast internet anywhere in Nigeria. Same-day service across Lagos & Abuja.\n\n⚡ CALL / WHATSAPP: 0802 279 1227\nBethelmind Digital Solutions (CAC Reg: 9912717)\nTap \"Start Chat\" on Jiji or message us on WhatsApp with your location to schedule installation!"
  };

  function setNative(el, val) {
    if (!el) return;
    const setter = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value')?.set;
    if (setter) setter.call(el, val); else el.value = val;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    el.dispatchEvent(new Event('blur', { bubbles: true }));
  }

  // 1. Fill Title
  const titleInput = document.querySelector('input[placeholder*="Title" i], input[name*="title" i], input[aria-label*="Title" i]');
  if (titleInput) {
    setNative(titleInput, AD.title);
    console.log('✅ Title populated: ' + AD.title);
  }

  // 2. Attach Unique Photo
  if (AD.imgB64) {
    try {
      const binary = atob(AD.imgB64);
      const array = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) array[i] = binary.charCodeAt(i);
      const blob = new Blob([array], { type: 'image/png' });
      const file = new File([blob], AD.imgName, { type: 'image/png' });
      const dt = new DataTransfer();
      dt.items.add(file);
      const fileInput = document.querySelector('input[type="file"]');
      if (fileInput) {
        fileInput.files = dt.files;
        fileInput.dispatchEvent(new Event('change', { bubbles: true }));
        fileInput.dispatchEvent(new Event('input', { bubbles: true }));
        console.log('✅ 3D High-End Photo attached for Ad #14!');
      }
    } catch (e) {
      console.warn('Photo notice:', e.message);
    }
  }

  // 3. Fill Description if on Step 2
  const descBox = document.querySelector('textarea, div[contenteditable="true"]');
  if (descBox) {
    if (descBox.tagName === 'TEXTAREA') setNative(descBox, AD.desc);
    else { descBox.innerText = AD.desc; descBox.dispatchEvent(new Event('input', { bubbles: true })); }
    console.log('✅ Description populated for Ad #14');
  }

  // 4. Fill Price if on Step 2
  const priceBox = document.querySelector('input[type="number"], input[placeholder*="Price" i], input[name*="price" i]');
  if (priceBox) {
    setNative(priceBox, String(AD.price));
    console.log('✅ Price (' + AD.priceStr + ') populated for Ad #14');
  }

  console.log('🎉 Ad #14 Autofill Completed Successfully!');
})();
